CREATE OR REPLACE FUNCTION public.grant_monthly_coins(p_user_id uuid, p_tier text, p_period_end timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'auto'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_amount      integer;
  v_override    integer;
  v_wallet      coin_wallets%ROWTYPE;
  v_anchor      int;
  v_created     timestamptz;
  v_has_billing boolean;
  v_is_comped   boolean;
  v_due         timestamptz;
  v_next        timestamptz;
  v_new_inc     integer;
  v_delta       integer;
  v_ref         text;
begin
  if p_tier not in ('free','premium','pro','business') then
    return jsonb_build_object('granted', false, 'reason', 'invalid_tier');
  end if;

  select value into v_amount from coin_config where key = 'monthly_grant_' || p_tier;
  if v_amount is null then
    return jsonb_build_object('granted', false, 'reason', 'grant_not_configured');
  end if;

  select monthly_grant_override, created_at,
         (stripe_customer_id is not null
          or apple_original_transaction_id is not null
          or google_purchase_token is not null),
         coalesce(is_comped, false)
    into v_override, v_created, v_has_billing, v_is_comped
  from profiles where id = p_user_id;

  if v_override is not null and v_override > 0 then
    v_amount := v_override;
  end if;

  insert into coin_wallets (user_id) values (p_user_id) on conflict (user_id) do nothing;
  select * into v_wallet from coin_wallets where user_id = p_user_id for update;

  v_anchor := coalesce(v_wallet.grant_anchor_day,
                       extract(day from coalesce(v_created, now()))::int);
  v_due := v_wallet.next_grant_at;

  if v_due is not null then
    if p_source = 'payment' then
      if v_due > now() + interval '2 days' then
        return jsonb_build_object('granted', false, 'reason', 'already_granted',
                                  'next_grant_at', v_due);
      end if;
    elsif v_due > now() then
      return jsonb_build_object('granted', false, 'reason', 'already_granted',
                                'next_grant_at', v_due);
    end if;
  end if;

  -- Pas de paiement, pas de grant — SAUF compte offert (is_comped) : personne
  -- ne paie pour lui, et il garde souvent un identifiant de paiement d'une
  -- periode anterieure. coins_awaiting_payment() porte la MEME condition.
  if p_source <> 'payment' and v_has_billing and not v_is_comped and p_tier <> 'free'
     and v_due is not null and v_due < now() - interval '3 days' then
    return jsonb_build_object('granted', false, 'reason', 'awaiting_payment_event',
                              'next_grant_at', v_due, 'tier', p_tier);
  end if;

  -- ── REMPLACEMENT (2026-09-02) — les Pépites incluses du mois sont pour le
  -- mois. L'ancien cumul plafonné (greatest/least, cap ×2) est retiré : le
  -- solde inclus devient le grant du palier, ni plus, ni moins. v_delta peut
  -- être négatif (solde de la veille > grant) : la ligne de ledger le porte
  -- tel quel, c'est la trace honnête du remplacement.
  -- purchased_balance n'apparaît nulle part ici — il ne bouge JAMAIS.
  v_new_inc := v_amount;
  v_delta   := v_new_inc - v_wallet.included_balance;

  if p_period_end is not null and p_period_end > now() then
    v_next := p_period_end;
  else
    v_next := grant_next_due(now(), v_anchor);
  end if;

  v_ref := 'grant_monthly:' || p_user_id || ':' || to_char(coalesce(v_due, now()), 'YYYY-MM-DD');
  begin
    insert into coin_ledger (user_id, delta, included_after, purchased_after, kind, ref, metadata)
    values (
      p_user_id, v_delta, v_new_inc, v_wallet.purchased_balance,
      'grant_monthly', v_ref,
      jsonb_build_object('tier', p_tier, 'override', v_override,
                         'source', p_source,
                         'solde_avant', v_wallet.included_balance,
                         'montant_theorique', v_amount,
                         'remplacement', true,
                         'next_grant_at', v_next)
    );
  exception when unique_violation then
    return jsonb_build_object('granted', false, 'reason', 'already_granted', 'ref', v_ref);
  end;

  -- (15/10, lot D) Le solde et l'échéance ne bougent QU'AVEC leur ligne.
  update coin_wallets set
    included_balance = v_new_inc,
    next_grant_at    = v_next,
    grant_anchor_day = v_anchor,
    updated_at       = now()
  where user_id = p_user_id;

  return jsonb_build_object('granted', true, 'amount', v_delta,
                            'montant_theorique', v_amount,
                            'solde_avant', v_wallet.included_balance,
                            'included_after', v_new_inc,
                            'next_grant_at', v_next,
                            'source', p_source);
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_monthly_coins_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_granted   int := 0;
  v_skipped   int := 0;
  v_awaiting  int := 0;
  v_purges    int := 0;
  v_abandons  int := 0;
  v_rendus    int := 0;
  v_scans_purges int := 0;
  r   record;
  s   record;
  res jsonb;
begin
  -- Purge du cache identify expiré (> 24 h). Best-effort : elle ne conditionne
  -- JAMAIS la fraîcheur (vérifiée à la lecture), elle évite juste la croissance
  -- sans fin de la table.
  delete from lens_identify_cache where created_at < now() - interval '24 hours';
  get diagnostics v_purges = row_count;

  -- Scans vivants dont plus rien ne viendra : réservation jamais partie
  -- ('preparation') ou runtime jamais revenu ('en_cours'). Requalifiés en
  -- échec, et remboursés s'ils avaient coûté quelque chose. Boucle et non
  -- UPDATE de masse : refund_coins doit être appelé ligne à ligne.
  for s in
    select scan_id, user_id, coins_debites, statut
    from lens_scans
    where statut in ('preparation', 'en_cours')
      and created_at < now() - interval '30 minutes'
  loop
    update lens_scans
       set statut = 'echec',
           motif  = case when s.statut = 'preparation'
                      then jsonb_build_object('code', 'abandon_avant_envoi',
                             'message', 'scan réservé dont la requête n''est jamais partie — requalifié par le sweep')
                      else jsonb_build_object('code', 'abandon_runtime',
                             'message', 'scan réservé jamais terminé — requalifié par le sweep')
                    end,
           termine_le = now()
     where scan_id = s.scan_id;
    v_abandons := v_abandons + 1;
    if s.coins_debites > 0 then
      perform refund_coins(
        s.user_id, s.coins_debites,
        jsonb_build_object('source', 'lens_analysis_failed',
                           'motif', 'abandon_runtime',
                           'scan_id', s.scan_id)
      );
      v_rendus := v_rendus + s.coins_debites;
    end if;
  end loop;

  -- Fenêtre d'audit qualité : 90 jours.
  delete from lens_scans where created_at < now() - interval '90 days';
  get diagnostics v_scans_purges = row_count;

  for r in
    select p.id,
           case
             when p.is_business = true then 'business'
          when p.is_pro = true then 'pro'
             when p.is_premium = true or p.is_comped = true then 'premium'
             else 'free'
           end as tier
    from profiles p
    -- LEFT JOIN impératif : un profil sans ligne coin_wallets doit être balayé,
    -- sinon il ne serait jamais crédité. next_grant_at vaut alors NULL.
    left join coin_wallets w on w.user_id = p.id
    where w.next_grant_at is null or w.next_grant_at <= now()
  loop
    res := upgrade_monthly_grant(r.id, r.tier, null, 'sweep');
    if coalesce((res->>'granted')::boolean, false) then
      v_granted := v_granted + 1;
    elsif res->>'reason' = 'awaiting_payment_event' then
      v_awaiting := v_awaiting + 1;
    else
      v_skipped := v_skipped + 1;
    end if;
  end loop;
  return jsonb_build_object('granted', v_granted, 'skipped', v_skipped,
                            'awaiting_payment', v_awaiting,
                            'lens_cache_purge', v_purges,
                            'lens_scans_abandonnes', v_abandons,
                            'lens_scans_unites_rendues', v_rendus,
                            'lens_scans_purges', v_scans_purges,
                            'ran_at', now());
end;
$function$
